#requires -Modules @{ ModuleName = 'Pester'; ModuleVersion = '5.0.0' }

<#
    Unit tests for the Test Results Aggregator library.

    These tests are written red/green TDD style: each describes one piece of
    behaviour of the library functions in TestResultsAggregator.ps1. They call
    the library functions directly so the red/green cycle is fast (the full
    end-to-end pipeline is exercised separately through `act` in
    Workflow.Tests.ps1).
#>

BeforeAll {
    # Dot-source the library under test. $PSScriptRoot is the tests/ directory.
    $script:RepoRoot = Split-Path -Parent $PSScriptRoot
    . (Join-Path $RepoRoot 'TestResultsAggregator.ps1')
    $script:FixturesDir = Join-Path $RepoRoot 'fixtures'
}

Describe 'Import-JUnitResult' {
    It 'parses every <testcase> from a JUnit XML file' {
        $results = Import-JUnitResult -Path (Join-Path $FixturesDir 'run1.junit.xml')
        $results.Count | Should -Be 6
    }
}

